# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Api::V1::Payments#create billing fence", type: :request do
  # "Every invoice, line-item, invoice-tax and payment write, mobile-collection payments included,
  # gets 503 ownership_moving while handoff_step is set and writes nothing"
  it "answers a manual payment with 503 ownership_moving and leaves payments and the invoice unchanged during a handoff" do
    company = create(:company)
    client = create(:client, company:)
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    user.add_role :admin, company
    sign_in user
    invoice = create(:invoice, company:, client:, status: "sent", amount: 100, amount_due: 100, amount_paid: 0)
    before_state = invoice.reload.attributes.slice("status", "amount_due", "amount_paid", "outstanding_amount")
    TimekeepingOwnership.current.update!(handoff_step: "close_admission")
    payment = { invoice_id: invoice.id, transaction_date: Date.current, transaction_type: "visa", amount: 100, note: "fence" }

    expect {
      send_request :post, api_v1_payments_path(payment:), headers: auth_headers(user)
    }.not_to change(Payment, :count)

    expect(response).to have_http_status(:service_unavailable)
    expect(json_response["reason"]).to eq("ownership_moving")
    expect(invoice.reload.attributes.slice("status", "amount_due", "amount_paid", "outstanding_amount")).to eq(before_state)
  end
end
